public sealed record Result<T>(bool IsSuccess, T? Value, string? Error)
{
    public static Result<T> Ok(T value) => new(true, value, null);
    public static Result<T> Fail(string error) => new(false, default, error);
}

public Result<Order> Place(PlaceOrder cmd)
{
    if (cmd.Quantity <= 0) return Result<Order>.Fail("quantity must be positive");
    if (!_catalog.Exists(cmd.Sku)) return Result<Order>.Fail($"unknown sku {cmd.Sku}");
    return Result<Order>.Ok(new Order(cmd.Sku, cmd.Quantity));
}

// In an endpoint: expected failures map to 400/404, not to 500.
var result = service.Place(cmd);
return result.IsSuccess ? Results.Ok(result.Value) : Results.BadRequest(result.Error);

public sealed class InsufficientFundsException : Exception
{
    public InsufficientFundsException(string accountId, decimal balance, decimal requested)
        : base($"Account {accountId} has {balance} but {requested} was requested.")
        => (AccountId, Balance, Requested) = (accountId, balance, requested);

    public string AccountId { get; }
    public decimal Balance { get; }
    public decimal Requested { get; }
}

